module serial2parallel (
	input clk, rst_n, din_valid,
	input din_serial,
	output reg [7:0] dout_parallel,
	output reg dout_valid
);
//==============================================//
//             Parameter and Integer            //
//==============================================//
integer i;
localparam IDLE 			= 2'b00;
localparam LOADING 		= 2'b01;
localparam OUTPUTTING 	= 2'b10;
//==============================================//
//            FSM State Declaration             //
//==============================================//
reg [1:0] curr_state, next_state;
//==============================================//
//                 Reg Declaration              //
//==============================================//
reg [3:0] cnt;
//==============================================//
//                  Wire Declaration            //
//==============================================//
//==============================================//
//            Continuous Assignment             //
//==============================================//
//==============================================//
//               Always Block                   //
//==============================================//
// Sequential always block
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		curr_state <= IDLE;
	end
	else begin
		curr_state <= next_state;
	end
end
// Combinational always block
always@(*) begin
	case(curr_state)
		IDLE: begin
			if(din_valid)
				next_state = LOADING;
			else
				next_state = IDLE;
		end

		LOADING: begin
			if(cnt==4'd8)
				next_state = OUTPUTTING;
			else
				next_state = LOADING;
		end

		default: begin
			next_state = IDLE;
		end	
	endcase
end
//==============================================//
//                  Output Block                //
//==============================================//
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		cnt <= 4'd0;
	end
	else begin
		case(curr_state)
			IDLE: begin
				cnt <= 4'd0;
			end

			LOADING: begin
				cnt <= cnt + 4'd1;
			end

			default: begin
				cnt <= 4'd0;
			end
		endcase
	end
end
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		for(i=0;i<8;i=i+1) begin
			dout_parallel[i] <= 1'd0;
		end
	end
	else begin
		case(curr_state)
			LOADING: begin
				dout_parallel[cnt] <= din_serial;
			end

			default: begin
				for(i=0;i<8;i=i+1) begin
					dout_parallel[i] <= dout_parallel[i];
				end
			end
		endcase
	end
end
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		dout_valid <= 1'd0;
	end
	else begin
		case(curr_state)
			OUTPUTTING: begin
				dout_valid <= 1'd1;
			end

			default: begin
				dout_valid <= 1'd0;
			end
		endcase
	end
end
endmodule
